import{_ as s,H as p,f as e,i as n}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"01 | 失效的访问控制：攻击者如何获取其他用户信息？","description":"","frontmatter":{},"headers":[{"level":2,"title":"访问控制","slug":"访问控制","link":"#访问控制","children":[]},{"level":2,"title":"案例实战","slug":"案例实战","link":"#案例实战","children":[{"level":3,"title":"意外的代理访问","slug":"意外的代理访问","link":"#意外的代理访问","children":[]},{"level":3,"title":"CVE-2010-1637 漏洞","slug":"cve-2010-1637-漏洞","link":"#cve-2010-1637-漏洞","children":[]}]},{"level":2,"title":"安全建设方案","slug":"安全建设方案","link":"#安全建设方案","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web漏洞挖掘实战/01｜失效的访问控制：攻击者如何获取其他用户信息？.md","filePath":"Web漏洞挖掘实战/01｜失效的访问控制：攻击者如何获取其他用户信息？.md","lastUpdated":1795536081000}'),l={name:"Web漏洞挖掘实战/01｜失效的访问控制：攻击者如何获取其他用户信息？.md"};function i(t,a,o,c,r,d){return p(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="_01-失效的访问控制-攻击者如何获取其他用户信息" tabindex="-1">01 | 失效的访问控制：攻击者如何获取其他用户信息？ <a class="header-anchor" href="#_01-失效的访问控制-攻击者如何获取其他用户信息" aria-label="Permalink to &quot;01 | 失效的访问控制：攻击者如何获取其他用户信息？&quot;">​</a></h1><p>你好，我是王昊天。</p><p>英文里有一句谚语你一定听说过，“Curiosity killed the cat”，翻译成中文是“好奇害死猫”。这句话是想告诉人们，不要为那些不必要的尝试去冒不可预知的风险，提醒人们不要过分好奇，否则会给自己带来伤害。但是在网络安全和编程领域，这句话却并不正确，因为正是对未知的好奇与探索，我们才能深入底层原理，写出更优雅的代码，构建出更安全的系统。</p><p>要知道，当处于对某种事物的属性出现认知空白时，动物往往想要弥补这份空白，是一种的非常本能心理，好奇心也由此产生。可以想象这样一个场景：当你构建了一个崭新的系统出现在用户面前，如果他们对这个系统充满了探索欲，那么这对于你来说无疑是非常愉快的体验。但是作为系统的构建者，你一定希望用户按照预先设定的规则、在预先搭建好的框架下开始他的旅程。而现实往往并非如此……</p><ul><li><p>某个脾气暴躁的用户由于没有耐心，直接通过 URL 跳过了认证界面；</p></li><li><p>某个健忘的用户由于记不住密码，通过找回登入了别人的账户；</p></li><li><p>某个好奇的用户由于想玩一下 API，意外访问到了其他人的信息；</p></li><li><p>某个专业的黑客由于心怀不轨，获取了你的管理员账户……</p></li></ul><p>你会发现，如果一个系统不存在有效的访问控制，那么这个系统一旦向用户开放使用，你将面临一场“灾难”。</p><h2 id="访问控制" tabindex="-1">访问控制 <a class="header-anchor" href="#访问控制" aria-label="Permalink to &quot;访问控制&quot;">​</a></h2><p>那么什么是访问控制呢？访问控制是一种策略，在这种策略的控制下，用户的操作不能逾越预设好的权限边界。而访问控制一旦失效通常会导致未认证信息泄露、内部数据篡改、数据删除和越权操作等后果。访问控制失效型问题通常有以下几种类型：</p><ol><li><p>系统在实现过程中违背了“最小权限原则” 或 “默认拒绝原则”，在这种情况下用户可以获得一些特殊权限，而这些特殊权限原本只应该授权给特定的用户或角色；</p></li><li><p>通过修改 URL 地址、内部程序状态、HTML 页面，或者使用 Cyber 工具修改 API 请求的方式绕过访问控制；</p></li><li><p>通过提供唯一 ID 的方式预览或者修改其他账户信息及数据；</p></li><li><p>未经过访问控制地通过 POST、PUT 和 DELETE 方法访问 API；</p></li><li><p>通常意义上的提权，比如未登录状态下的用户操作，或者常规用户登录状态下的管理员操作；</p></li><li><p>元数据操纵，比如重放或者修改 JWT（JSON Web Token）访问控制令牌，或者通过操纵Cookie 的方式进行提权；</p></li><li><p>CORS 误配置，可以导致来自未认证源的 API 访问。</p></li></ol><p>这里我们首先来看几种简单攻击场景。</p><ol><li>这个应用在 SQL 调用中直接使用了未经验证的数据，并利用该数据进行信息查询：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pstmt.setString(1, request.getParameter(&quot;acct&quot;));</span></span>
<span class="line"><span>ResultSet results = pstmt.executeQuery();</span></span></code></pre></div><p>对于一个攻击者而言，只需要简单地在浏览器地址栏中修改 acct 参数，即可对 SQL 语句进行操纵，而在未经验证的情况下，该攻击者可以访问到其他账户的信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/app/accountInfo?acct=notmyacct</span></span></code></pre></div><ol start="2"><li>一个攻击者可以很轻松地修改 URL 地址，尝试去访问他的目标链接，比如这里攻击者试图通过 URL 地址修改直接访问 admin 页面：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/app/getappInfo</span></span>
<span class="line"><span>https://example.com/app/admin_getappInfo</span></span></code></pre></div><p>如果攻击者成功访问了第二个链接，那么说明系统在权限设计和访问控制上就是存在问题的。</p><ol start="3"><li>由于实现过程中未对用户访问参数设置边界，导致了很多越权问题的发生：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/order/?order_id=2021102617429999</span></span></code></pre></div><p>攻击者可以尝试修改上述 API 接口中的 order_id 参数，使其在程序接口上的输入合法，但是对于用户而言却是越权行为。</p><ol start="4"><li>HTTP PUT 方法最早目的用于文件管理操作，可以对网站服务器中的文件实现更改删除的更新操作，该方法往往可以导致各种文件上传漏洞，造成严重的网站攻击事件：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>put /root/Desktop/shell.php</span></span></code></pre></div><p>上述代码在支持 PUT 方法的环境中，上传 Webshell 进行提权；在实际运用中，若必须启用该方法，则需要对该方法涉及文件资源做好严格的访问权限控制。</p><ol start="5"><li>Web 应用将身份认证结果直接存储在 Cookie 中，并未施加额外的保护措施：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cookie: role=user --&gt; Cookie: role=admin</span></span></code></pre></div><p>通过在 Web 前端拦截 Cookie，并进行 Cookie 内容修改即可提权。</p><ol start="6"><li>有些开发者为了方便，直接在 Access-Control-Allow-Origin 中反射请求的 Origin 值：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_header &quot;Access-Control-Allow-Origin&quot; $http_origin;</span></span>
<span class="line"><span>add_header “Access-Control-Allow-Credentials” “true”;</span></span></code></pre></div><p>这是一个错误的 Nginx 配置示例，这样的配置意味着信任任何网站，攻击者网站可以直接跨域读取其资源内容，窃取隐私数据。</p><h2 id="案例实战" tabindex="-1">案例实战 <a class="header-anchor" href="#案例实战" aria-label="Permalink to &quot;案例实战&quot;">​</a></h2><p>通过刚才几个简单的场景，相信你对访问控制已经有了一个初步的认知。接下来我们再来看一个更为复杂的攻击场景。</p><h3 id="意外的代理访问" tabindex="-1">意外的代理访问 <a class="header-anchor" href="#意外的代理访问" aria-label="Permalink to &quot;意外的代理访问&quot;">​</a></h3><p>如果一个应用从输入流组件接受到了外部的请求、消息或者命令，并且这些请求、消息或者命令没有经过有效的请求源处理就被转发到应用控制范围外的某个资产中，这时就会诱发一种访问控制失效风险。</p><p>想象一下，当你还在读书的时候，在学校里同学给了你一份蛋糕，希望你回家后可以转送给你的妹妹，而你到家之后由于疏忽直接把蛋糕给了妹妹并且没有任何说明，这时妹妹会以为这份蛋糕是你买给她的礼物，这就造成了一种误解。</p><p>回到我们所描述的技术场景，这个应用就是“你”的身份，而请求被转发的目标资产就是“你的妹妹”，这个应用此时成为了一种代理或者中间人的角色，使得不应该被访问到的资产被意外访问到了。</p><p>再稍微拓展开讲一讲，如果一个攻击者不能直接访问目标，但是一个应用可以，这时攻击者可以发送请求到应用，再让应用转发请求到最终目标。这种情况下，攻击请求看起来像是来自应用的访问，而非真实攻击者。这种攻击的效果很直观，可以直接绕过访问控制（如防火墙）或者隐蔽恶意请求源信息。</p><p>我们不仅需要知道这种风险的威力，还需要了解这种风险在什么情况下会出现。由于类似的消息转发或者代理功能大部分情况下都是正常功能，因此我们不能因噎废食，仅仅是因为有可能存在安全风险就抛弃正常功能。这就需要我们去了解，在什么情况下这种功能会变成一种漏洞：</p><ol><li><p>应用本身的权限和用户可以操纵的输入流组件所属的权限不同；（条件 A）</p></li><li><p>攻击者并不能够直接发送请求到最终目标资产；（条件 B）</p></li><li><p>攻击者能够创建一个可以被转发的请求，这个请求可能：</p></li></ol><ul><li><p>指向了未授权访问的域名、端口号、IP 以及服务；（条件 C）</p></li><li><p>指向了被授权访问的服务，但是请求内部包含了未授权的指令、资源等。（条件 D）</p></li></ul><p>用简单的公式来描述的话，就是只有在“A &amp;&amp; B &amp;&amp; ( C || D )”的情况下，消息转发或者代理功能才会成为一种安全风险或者安全漏洞。</p><h3 id="cve-2010-1637-漏洞" tabindex="-1">CVE-2010-1637 漏洞 <a class="header-anchor" href="#cve-2010-1637-漏洞" aria-label="Permalink to &quot;CVE-2010-1637 漏洞&quot;">​</a></h3><p>接下来我们看一个非常有趣的漏洞，它的编号是 CVE-2010-1637。这个漏洞会影响SquirrelMail 1.4.20 以及更早的版本，漏洞主要的发生点是 Mail Fetch 组件，由于该组件是SquirrelMail 的默认组件，因此该漏洞影响力还是很大的。如果该漏洞存在，那么经过认证的远程用户就可以得到允许绕过防火墙限制，将 SquirrelMail 作为一个代理（proxy）进一步扫描内网。</p><p>mail_fetch 是在 SquirrelMail 1.4.20 版本的一个默认组件:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hunter@HunterdeiMac &gt; ~/Downloads/squirrelmail-1.4.20/plugins &gt; tree mail_fetch</span></span>
<span class="line"><span>mail_fetch</span></span>
<span class="line"><span>├── README</span></span>
<span class="line"><span>├── class.POP3.php</span></span>
<span class="line"><span>├── fetch.php</span></span>
<span class="line"><span>├── functions.php</span></span>
<span class="line"><span>├── index.php</span></span>
<span class="line"><span>├── options.php</span></span>
<span class="line"><span>└── setup.php</span></span>
<span class="line"><span>0 directories, 7 files</span></span></code></pre></div><p>mail_fetch 的主要功能是通过使用 fsockopen() 这个 PHP 函数来模拟 POP3 协议，并且仅支持了 POST 方式的认证，并没有对 IP 以及端口号进行检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>...</span></span>
<span class="line"><span>if (!isset($port) || !$port) {$port = 110;}</span></span>
<span class="line"><span>   if(!empty($this-&gt;MAILSERVER))</span></span>
<span class="line"><span>   $server = $this-&gt;MAILSERVER;</span></span>
<span class="line"><span>   if(empty($server)){</span></span>
<span class="line"><span>     $this-&gt;ERROR = &quot;POP3 connect: &quot; . _(&quot;No server specified&quot;);</span></span>
<span class="line"><span>     unset($this-&gt;FP);</span></span>
<span class="line"><span>     return false;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>   // 老师加的注释</span></span>
<span class="line"><span>   // 此处缺乏对于服务器IP及端口号的检查</span></span>
<span class="line"><span>   $fp = @fsockopen(&quot;$server&quot;, $port, $errno, $errstr);</span></span>
<span class="line"><span>   if(!$fp) {</span></span>
<span class="line"><span>     $this-&gt;ERROR = &quot;POP3 connect: &quot; . _(&quot;Error &quot;) . &quot;[$errno] [$errstr]&quot;;</span></span>
<span class="line"><span>     unset($this-&gt;FP);</span></span>
<span class="line"><span>     return false;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>经过简单的分析，可以发现该代码段符合“A &amp;&amp; B &amp;&amp; ( C || D )”的漏洞存在条件，该处应该存在失效的访问控制。</p><p>找到了切入点，接下来你就可以通过下面三个步骤实现汽车变成汽车人的精彩过程——将SquirrelMail 变成 Nmap 扫描器：</p><ol><li><p>服务端先返回消息的 Service，比如 SSH 这种，通过对 TCP 服务的 Banner 信息抓取，可以了解目标资产提供的 Service；</p></li><li><p>客户端先发送消息的 Service，比如 HTTP 这种，POP3 对象在建立完 TCP 三次握手之后会进入阻塞状态，通过 fgets() 函数设置硬编码超时时间，可以判断目标端口是否开放；</p></li><li><p>由于仅仅支持 POST 方式认证，因此请求是以账户为前置条件去发送的，所以 Cookie 也是需要的。</p></li></ol><p>那么到现在为止，我们已经有了“汽车人”变形之后的完整功能设计图：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./squirrel-nmap [Target] [IP] [TCP_PORT] [Cookie]</span></span>
<span class="line"><span>- Target suqiremail的URL地址，如http://target.com/sqm/</span></span>
<span class="line"><span>- IP 待扫描的IP地址</span></span>
<span class="line"><span>- TCP_PORT 尝试探测的TCP端口号</span></span>
<span class="line"><span>- Cookie 经过认证的Cookie</span></span></code></pre></div><p>通过简单的实现，我们来看看实际的战斗威力如何：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./squirre-nmap &quot;http://target.com/squirrelmail-1.4/&quot; 192.168.1.4 22 &quot;key=dTPc00s%</span></span>
<span class="line"><span>Fetching from 192.168.1.4:22</span></span>
<span class="line"><span>Oops, POP3 connect: Error [SSH-2.0-OpenSSH 5.1p1 Debian-3]</span></span></code></pre></div><p>可以看到能够成功地对内网 IP 进行 Service 进行探测。</p><h2 id="安全建设方案" tabindex="-1">安全建设方案 <a class="header-anchor" href="#安全建设方案" aria-label="Permalink to &quot;安全建设方案&quot;">​</a></h2><p>通过这次探讨，你可以发现访问控制是授权或拒绝特定用户请求的过程。这个过程只有在应用开发的初始阶段就经过良好的设计，才能避免后续问题的发生。接下来我会提出一些优秀的访问控制设计原则，供你在实践中参考：</p><ol><li>优先开始设计访问控制体系</li></ol><p>访问控制不仅是应用安全设计的一项主要事务，而且应当被设置在非常优先的位置，因为往往访问控制的设计在起步阶段是相对简单的，但是会很快随着功能点的增多快速复杂化。所以，如果你考虑使用成熟的软件框架来完成访问控制，一定要确保其能够满足你未来的应用定制化需求。</p><ol start="2"><li>强制所有请求经过访问控制检查</li></ol><p>开发一个访问控制检查层（Layer），然后确保所有请求都在某种程度上经过这个检查层。以Java 的 filter 为例，许多自动化的请求处理机制都是能够帮助我们实现这种需求的技术形态。</p><ol start="3"><li>默认拒绝</li></ol><p>这是非常简单但是有效的策略，所谓默认拒绝是指，只要一个请求没有被指明是被允许的，那么它就是被拒绝的。</p><ol start="4"><li>不要硬编码角色</li></ol><p>很多应用框架默认使用用户角色来进行访问控制，以下的代码形态是很常见的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (user.hasRole(&quot;admin&quot;) || user.hasRole(&quot;Manager&quot;)) {</span></span>
<span class="line"><span> deleteAccount();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>但是你要对这种 Role-Based 编码模式格外留意，因为它可能会带来以下几种风险：</p><ul><li><p>由于这种编码自身的特性非常脆弱，很容易出现检查错误或者检查缺失等情况；</p></li><li><p>由于这种编码模型对于多租户产品非常不友好，很容易出现用户角色一致但是权限不一致的情况；</p></li><li><p>Role-Based 编码模型无法适配包括以数据为核心的以及横向访问控制；</p></li><li><p>当项目代码量攀升并且伴随着很多访问权限控制的情况出现时，访问控制策略的审计和验证是非常困难的。</p></li></ul><p>因此这里我更推荐你使用这种编码方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (user.hasAccess(&quot;DELETE_ACCOUNT&quot;)) {</span></span>
<span class="line"><span> deleteAccount();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>以属性或者功能为核心的访问控制编码模型，从特性上来讲更易于构建功能丰富的访问控制系统。</p><ol start="5"><li>记录所有的访问控制类事件</li></ol><p>所有的访问控制失效都应该有完整的记录，因为这些事件很可能成为恶意用户尝试寻找系统漏洞的线索。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课程我们学习了 2021 年 OWASP TOP 10 中排行第一的风险类别——失效的访问控制，访问控制是安全建设的第一关，也是最重要的一环 —— 它不仅和安全建设相关，更是产品功能的一个组成部分。</p><p>首先我们对访问控制的概念和范围进行了整体探讨，列举了一些典型的访问控制失效场景：</p><ol><li><p>系统实现过程中违背最小权限原则；</p></li><li><p>修改 API 参数实现越权；</p></li><li><p>提供唯一 ID 给用户预览数据；</p></li><li><p>未对 PUT、DELETE 防范进行限制；</p></li><li><p>元数据（JWT、Cookie）操纵；</p></li><li><p>CORS 误配置。</p></li></ol><p>然后针对这些典型的访问控制失效场景，我们展示了对应的问题代码。</p><p>在漏洞挖掘过程中，作为安全或者开发人员，我们要先对待挖掘的漏洞有清晰的认知，对于一些稍复杂的逻辑漏洞最好能够进行清晰的数学描述。</p><p>这里我们以“意外的代理访问”类型漏洞为例，抽象出了一个数学模型——“A &amp;&amp; B &amp;&amp; ( C || D)”用于该类漏洞的判断，并利用模型成功分析了一个 2010 年真实发生的的 0 Day 漏洞。</p><p>在最后一部分，我们对访问控制层面的安全建设做了分析，并且给出了一些优秀的设计层、编码层的建议：</p><ol><li><p>在系统构建阶段优先设计访问控制体系；</p></li><li><p>强制所有请求经过访问控制检查；</p></li><li><p>采用默认拒绝原则；</p></li><li><p>采取以权限为核心的编码原则；</p></li><li><p>记录所有访问控制类事件。</p></li></ol><p>以我们所探讨的安全建设方案为基础，相信你可以进行优雅的编码并设计出优秀的访问控制系统，构建起你的应用安全的第一道防线。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>除了这节课程我们提到的风险种类，访问控制失效你还能想到哪些风险类型呢？</p><p>期待你的思考，也欢迎你在留言中与我交流，或者转发给你的朋友加入讨论。我们下节课再见！</p>`,85)])])}const g=s(l,[["render",i]]);export{u as __pageData,g as default};
